    # Collapse each contiguous run of identical rows, preserving the first row.
    rows = []
    for row in grid:
        if not rows or row != rows[-1]:
            rows.append(row[:])

    # Then collapse each contiguous run of identical columns.
    if not rows:
        return []
    cols = []
    for c in range(len(rows[0])):
        col = tuple(row[c] for row in rows)
        if not cols or col != cols[-1]:
            cols.append(col)
    return [[col[r] for col in cols] for r in range(len(rows))]
